import fr.ska.mesheures.ReminderTimes;import java.util.*;
public class ReminderTimesTest {
 static long at(String day,String time,TimeZone zone){String[] d=day.split("-"),t=time.split(":");Calendar c=Calendar.getInstance(zone);c.clear();c.set(Integer.parseInt(d[0]),Integer.parseInt(d[1])-1,Integer.parseInt(d[2]),Integer.parseInt(t[0]),Integer.parseInt(t[1]));return c.getTimeInMillis();}
 public static void main(String[] args){TimeZone z=TimeZone.getTimeZone("Pacific/Tahiti");long monday=at("2026-10-05","07:00",z);if(ReminderTimes.next(monday,"08:00",31,z)!=at("2026-10-05","08:00",z))throw new AssertionError();if(ReminderTimes.next(at("2026-10-09","18:00",z),"08:00",31,z)!=at("2026-10-12","08:00",z))throw new AssertionError("weekend");if(ReminderTimes.next(at("2026-10-11","07:00",z),"08:00",64,z)!=at("2026-10-11","08:00",z))throw new AssertionError("dimanche");if(ReminderTimes.next(at("2026-10-05","08:00",z),"08:00",1,z)!=at("2026-10-12","08:00",z))throw new AssertionError("heure passée");if(ReminderTimes.next(monday,"25:00",31,z)!=-1||ReminderTimes.next(monday,"08:00",0,z)!=-1)throw new AssertionError("validation");if(!ReminderTimes.shouldNotify(0,false,0)||ReminderTimes.shouldNotify(0,true,0)||!ReminderTimes.shouldNotify(1,true,0)||ReminderTimes.shouldNotify(1,false,0)||ReminderTimes.shouldNotify(1,true,7200001))throw new AssertionError("pointage");TimeZone paris=TimeZone.getTimeZone("Europe/Paris");if(ReminderTimes.next(at("2026-10-24","20:00",paris),"08:00",64,paris)!=at("2026-10-25","08:00",paris))throw new AssertionError("fuseau");System.out.println("OK : jours, week-end, horaires, fuseau, validation et conditions arrivée/départ");}
}
